{"id": "train_spider:564", "question_original_en": "papers that are coauthored by Peter Mertens and Dina Barbian", "sql": "SELECT DISTINCT t3.paperid FROM writes AS t3 JOIN author AS t2 ON t3.authorid  =  t2.authorid JOIN writes AS t4 ON t4.paperid  =  t3.paperid JOIN author AS t1 ON t4.authorid  =  t1.authorid WHERE t2.authorname  =  "Peter Mertens" AND t1.authorname  =  "Dina Barbian";", "schema": "CREATE TABLE `author` (
  `authorId` integer NOT NULL
,  `authorName` varchar(50) DEFAULT NULL
,  PRIMARY KEY (`authorId`)
);

CREATE TABLE `cite` (
  `citingPaperId` integer NOT NULL
,  `citedPaperId` integer NOT NULL
,  PRIMARY KEY (`citingPaperId`,`citedPaperId`)
,  FOREIGN KEY(`citedpaperId`) REFERENCES `paper`(`paperId`)
,  FOREIGN KEY(`citingpaperId`) REFERENCES `paper`(`paperId`)
);

